import java.util.*;

public class Solution {
    public boolean makeEqual(String[] words) {
        if (words == null || words.length == 0) {
            return true;
        }
        int n = words.length;
        int[] freq = new int[26];
        for (String w : words) {
            if (w != null) {
                for (int i = 0; i < w.length(); i++) {
                    char c = w.charAt(i);
                    if (c >= 'a' && c <= 'z') {
                        freq[c - 'a']++;
                    }
                }
            }
        }
        for (int count : freq) {
            if (count % n != 0) {
                return false;
            }
        }
        return true;
    }
}

