    public int countDifferentSubsequenceGCDs(int[] nums) {
        int max = 0;
        for (int v : nums) {
            if (v > max) max = v;
        }
        int[] freq = new int[max + 1];
        for (int v : nums) {
            freq[v]++;
        }

        int count = 0;
        for (int g = 1; g <= max; g++) {
            int currentGcd = 0;
            boolean hasMultiple = false;
            for (int multiple = g; multiple <= max; multiple += g) {
                if (freq[multiple] > 0) {
                    hasMultiple = true;
