                        currentGcd = gcd(currentGcd, multiple);
                    }
                    // early exit if gcd already equals g
                    if (currentGcd == g) {
                        // we can break early only after confirming at least one multiple exists
                        // but continue to consume loop to keep logic simple
                    }
                }
            }
            if (hasMultiple && currentGcd == g) {
                count++;
            }
        }
        return count;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

