public class Solution {
    public int minSpeedOnTime(int[] dist, double hour) {
        int n = dist.length;
        // If hour is less than the minimum possible integer hours for the first n-1 trips, impossible
        if (hour <= n - 1) {
            // Only possible when there is exactly one train
            if (n == 1 && hour >= (double) dist[0] / 1e7) {
                // continue to binary search, will handle
            } else {
                return -1;
            }
        }

        int left = 1;
        int right = 10_000_000; // given constraint that answer will not exceed 1e7

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canFinish(dist, hour, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return canFinish(dist, hour, left) ? left : -1;
    }

    private boolean canFinish(int[] dist, double hour, int speed) {
        double time = 0.0;
        int n = dist.length;
        for (int i = 0; i < n - 1; i++) {
            time += Math.ceil(dist[i] / (double) speed);
            if (time > hour) {
                return false; // early exit
            }
        }
        time += dist[n - 1] / (double) speed;
        return time <= hour;
    }
}

