public class Solution {
    private static final int MOD = 1_000_000_007;

    public int getNumberOfBacklogOrders(int[][] orders) {
        // Max-heap for buy orders (highest price first)
        PriorityQueue<int[]> buy = new PriorityQueue<>(new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                return Integer.compare(b[0], a[0]);
            }
        });

        // Min-heap for sell orders (lowest price first)
        PriorityQueue<int[]> sell = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));

        for (int[] order : orders) {
            int price = order[0];
            long amount = order[1];
            int type = order[2]; // 0 = buy, 1 = sell

            if (type == 0) { // buy order
                while (amount > 0 && !sell.isEmpty() && sell.peek()[0] <= price) {
                    int[] bestSell = sell.peek();
                    long sellAmt = bestSell[1];
                    if (sellAmt > amount) {
                        bestSell[1] = (int) (sellAmt - amount);
                        amount = 0;
                    } else {
                        amount -= sellAmt;
                        sell.poll();
                    }
                }
                if (amount > 0) {
                    buy.offer(new int[]{price, (int) amount});
                }
            } else { // sell order
                while (amount > 0 && !buy.isEmpty() && buy.peek()[0] >= price) {
                    int[] bestBuy = buy.peek();
                    long buyAmt = bestBuy[1];
                    if (buyAmt > amount) {
                        bestBuy[1] = (int) (buyAmt - amount);
                        amount = 0;
                    } else {
                        amount -= buyAmt;
                        buy.poll();
                    }
                }
                if (amount > 0) {
                    sell.offer(new int[]{price, (int) amount});
                }
            }
        }

        long total = 0;
        for (int[] b : buy) {
            total = (total + b[1]) % MOD;
        }
        for (int[] s : sell) {
            total = (total + s[1]) % MOD;
        }
        return (int) total;
    }
}

