import java.util.*;

public class Solution {
    public int getMinSwaps(String num, int k) {
        char[] target = num.toCharArray();
        // generate the k-th next permutation
        for (int cnt = 0; cnt < k; cnt++) {
            nextPermutation(target);
        }

        char[] cur = num.toCharArray();
        int n = cur.length;
        int swaps = 0;

        for (int i = 0; i < n; i++) {
            if (cur[i] == target[i]) {
                continue;
            }
            int j = i + 1;
            while (j < n && cur[j] != target[i]) {
                j++;
            }
            // bring cur[j] to position i by swapping leftwards
            while (j > i) {
                char tmp = cur[j];
                cur[j] = cur[j - 1];
                cur[j - 1] = tmp;
                swaps++;
                j--;
            }
        }
        return swaps;
    }

    private void nextPermutation(char[] arr) {
        int n = arr.length;
        int i = n - 2;
        while (i >= 0 && arr[i] >= arr[i + 1]) {
            i--;
        }
        if (i >= 0) {
            int j = n - 1;
            while (arr[j] <= arr[i]) {
                j--;
            }
            swap(arr, i, j);
        }
        reverse(arr, i + 1, n - 1);
    }

    private void swap(char[] arr, int i, int j) {
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private void reverse(char[] arr, int left, int right) {
        while (left < right) {
            swap(arr, left, right);
            left++;
            right--;
        }
    }
}

