import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int minOperationsToFlip(String expression) {
        Deque<int[]> values = new ArrayDeque<>();
        Deque<Character> ops = new ArrayDeque<>();

        for (int i = 0; i < expression.length(); i++) {
            char c = expression.charAt(i);
            if (c == '0' || c == '1') {
                int[] cost = new int[2];
                cost[0] = (c == '0') ? 0 : 1; // cost to make 0
                cost[1] = (c == '1') ? 0 : 1; // cost to make 1
                values.push(cost);
            } else if (c == '(') {
                ops.push(c);
            } else if (c == ')') {
                while (ops.peek() != '(') {
                    applyOp(values, ops);
                }
                ops.pop(); // remove '('
            } else if (c == '&' || c == '|') {
                // evaluate previous operators (left‑to‑right, no precedence)
                while (!ops.isEmpty() && ops.peek() != '(') {
                    applyOp(values, ops);
                }
                ops.push(c);
            }
        }

        while (!ops.isEmpty()) {
            applyOp(values, ops);
        }

        int[] finalCost = values.pop();
        // original value is the one with zero cost
        int original = (finalCost[0] == 0) ? 0 : 1;
        return original == 0 ? finalCost[1] : finalCost[0];
    }

    private void applyOp(Deque<int[]> values, Deque<Character> ops) {
        char op = ops.pop();
        int[] right = values.pop();
        int[] left = values.pop();
        int[] res = new int[2]; // res[0] = min cost to get 0, res[1] = min cost to get 1

        // without flipping the operator
        if (op == '&') {
            // result 0: at least one side is 0
            res[0] = Math.min(
                    left[0] + Math.min(right[0], right[1]),
                    right[0] + Math.min(left[0], left[1])
            );
            // result 1: both sides are 1
            res[1] = left[1] + right[1];
        } else { // op == '|'
            // result 1: at least one side is 1
            res[1] = Math.min(
                    left[1] + Math.min(right[0], right[1]),
                    right[1] + Math.min(left[0], left[1])
            );
            // result 0: both sides are 0
            res[0] = left[0] + right[0];
        }

        // consider flipping the operator (cost +1)
        if (op == '&') {
            // treat as '|'
            int flip0 = left[0] + right[0] + 1; // both 0 for '|'
            int flip1 = Math.min(
                    left[1] + Math.min(right[0], right[1]),
                    right[1] + Math.min(left[0], left[1])
            ) + 1;
            res[0] = Math.min(res[0], flip0);
            res[1] = Math.min(res[1], flip1);
        } else { // op == '|'
            // treat as '&'
            int flip0 = Math.min(
                    left[0] + Math.min(right[0], right[1]),
                    right[0] + Math.min(left[0], left[1])
            ) + 1;
            int flip1 = left[1] + right[1] + 1;
            res[0] = Math.min(res[0], flip0);
            res[1] = Math.min(res[1], flip1);
        }

        values.push(res);
    }
}

