import java.util.*;

public class Solution {
    public boolean areSentencesSimilar(String sentence1, String sentence2) {
        String[] w1 = sentence1.split(" ");
        String[] w2 = sentence2.split(" ");

        int i = 0, j = 0;
        // match common prefix
        while (i < w1.length && j < w2.length && w1[i].equals(w2[j])) {
            i++;
            j++;
        }

        int iEnd = w1.length - 1;
        int jEnd = w2.length - 1;
        // match common suffix
        while (iEnd >= i && jEnd >= j && w1[iEnd].equals(w2[jEnd])) {
            iEnd--;
            jEnd--;
        }

        // if either remaining part is empty, sentences are similar
        return i > iEnd || j > jEnd;
    }
}

