import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    private long modPow(long a, long e) {
        long res = 1;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * a) % MOD;
            }
            a = (a * a) % MOD;
            e >>= 1;
        }
        return res;
    }

    public int makeStringSorted(String s) {
        int n = s.length();
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        int[] freq = new int[256];
        for (int i = 0; i < n; i++) {
            freq[s.charAt(i)]++;
        }

        long rank = 0;
        for (int pos = 0; pos < n; pos++) {
            int cur = s.charAt(pos);
            // try placing a smaller character at this position
            for (int c = 0; c < cur; c++) {
                if (freq[c] == 0) continue;
                freq[c]--;
                long perms = fact[n - pos - 1];
                for (int k = 0; k < 256; k++) {
                    perms = perms * invFact[freq[k]] % MOD;
                }
                rank = (rank + perms) % MOD;
                freq[c]++; // restore
            }
            // fix current character and move to next position
            freq[cur]--;
        }

        return (int) rank;
    }
}

