public class Solution {
    public int minFlips(String s) {
        int n = s.length();
        if (n == 0) return 0;
        String doubled = s + s;
        int len = 2 * n;

        int[] diff0 = new int[len];
        int[] diff1 = new int[len];

        for (int i = 0; i < len; i++) {
            char c = doubled.charAt(i);
            char expected0 = (i % 2 == 0) ? '0' : '1';
            char expected1 = (i % 2 == 0) ? '1' : '0';
            diff0[i] = (c == expected0) ? 0 : 1;
            diff1[i] = (c == expected1) ? 0 : 1;
        }

        int minFlips = Integer.MAX_VALUE;

        // Sliding window for pattern starting with '0'
        int windowSum = 0;
        for (int i = 0; i < n; i++) {
            windowSum += diff0[i];
        }
        minFlips = Math.min(minFlips, windowSum);
        for (int i = n; i < len; i++) {
            windowSum += diff0[i];
            windowSum -= diff0[i - n];
            minFlips = Math.min(minFlips, windowSum);
        }

        // Sliding window for pattern starting with '1'
        windowSum = 0;
        for (int i = 0; i < n; i++) {
            windowSum += diff1[i];
        }
        minFlips = Math.min(minFlips, windowSum);
        for (int i = n; i < len; i++) {
            windowSum += diff1[i];
            windowSum -= diff1[i - n];
            minFlips = Math.min(minFlips, windowSum);
        }

        return minFlips;
    }
}

