public class Solution {
    private static final int MOD = 1_000_000_007;

    public int rearrangeSticks(int n, int k) {
        if (k > n || k < 0) return 0;
        long[] dp = new long[k + 1];
        dp[0] = 1; // dp[0][0] = 1

        for (int i = 1; i <= n; i++) {
            long[] ndp = new long[k + 1];
            int upper = Math.min(i, k);
            for (int j = 1; j <= upper; j++) {
                long addNew = dp[j - 1];                     // place the longest stick at the end
                long extend = (long) (i - 1) * dp[j];        // place it somewhere else
                ndp[j] = (addNew + extend) % MOD;
            }
            dp = ndp;
        }
        return (int) dp[k];
    }
}

