import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public class Solution {
    private static class State {
        int n, a, b;
        State(int n, int a, int b) {
            this.n = n;
            this.a = a;
            this.b = b;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof State)) return false;
            State s = (State) o;
            return n == s.n && a == s.a && b == s.b;
        }
        @Override
        public int hashCode() {
            return Objects.hash(n, a, b);
        }
    }

    private final Map<State, int[]> memo = new HashMap<>();

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        if (firstPlayer > secondPlayer) {
            int tmp = firstPlayer;
            firstPlayer = secondPlayer;
            secondPlayer = tmp;
        }
        return dfs(n, firstPlayer, secondPlayer);
    }

    private int[] dfs(int n, int a, int b) {
        if (a + b == n + 1) {
            return new int[]{1, 1};
        }
        State key = new State(n, a, b);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int newN = (n + 1) / 2; // number of players in next round
        int baseA = (a - 1) / 2;
        int crossA = Math.min(a - 1, n - a + 1);
        int baseB = (b - 1) / 2;
        int crossB = Math.min(b - 1, n - b + 1);

        int earliest = Integer.MAX_VALUE;
        int latest = Integer.MIN_VALUE;

        for (int newA = baseA + 1; newA <= baseA + crossA + 1; newA++) {
            for (int newB = baseB + 1; newB <= baseB + crossB + 1; newB++) {
                if (newA >= newB) continue;
                if (newA > newN || newB > newN) continue;
                int[] sub = dfs(newN, newA, newB);
                earliest = Math.min(earliest, 1 + sub[0]);
                latest = Math.max(latest, 1 + sub[1]);
            }
        }

        int[] result = new int[]{earliest, latest};
        memo.put(key, result);
        return result;
    }
}

