    public int minSwaps(String s) {
        int n = s.length();
        int totalZeros = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') totalZeros++;
        }

        int answer = Integer.MAX_VALUE;

        // Pattern starting with '0' -> 0,1,0,1,...
        int neededZerosPattern0 = (n + 1) / 2; // ceil(n/2)
        if (totalZeros == neededZerosPattern0) {
            int mismatches01 = 0; // positions where expected '0' but got '1'
            for (int i = 0; i < n; i++) {
                char expected = (i % 2 == 0) ? '0' : '1';
                if (s.charAt(i) != expected && s.charAt(i) == '1') {
                    mismatches01++;
                }
            }
            answer = Math.min(answer, mismatches01);
        }

        // Pattern starting with '1' -> 1,0,1,0,...
        int neededZerosPattern1 = n / 2; // floor(n/2)
        if (totalZeros == neededZerosPattern1) {
            int mismatches01 = 0; // positions where expected '0' but got '1'
            for (int i = 0; i < n; i++) {
                char expected = (i % 2 == 0) ? '1' : '0';
                if (s.charAt(i) != expected && s.charAt(i) == '1') {
                    mismatches01++;
                }
            }
            answer = Math.min(answer, mismatches01);
        }

        return answer == Integer.MAX_VALUE ? -1 : answer;
