        int roomPtr = 0;

        for (int[] query : qInfo) {
            int minSize = query[0];
            int preferred = query[1];
            int idx = query[2];

            // Add all rooms that satisfy size requirement
            while (roomPtr < n && rooms[roomPtr][1] >= minSize) {
                ids.add(rooms[roomPtr][0]);
                roomPtr++;
            }

            if (ids.isEmpty()) {
                answer[idx] = -1;
                continue;
            }

            Integer lower = ids.floor(preferred);
            Integer higher = ids.ceiling(preferred);

            int bestId = -1;
            int bestDiff = Integer.MAX_VALUE;

            if (lower != null) {
                bestId = lower;
                bestDiff = Math.abs(lower - preferred);
            }
            if (higher != null) {
                int diff = Math.abs(higher - preferred);
                if (diff < bestDiff || (diff == bestDiff && higher < bestId)) {
                    bestId = higher;
                    bestDiff = diff;
                }
            }
            answer[idx] = bestId;
        }

        return answer;
    }
}

