import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maxHappyGroups(int batchSize, int[] groups) {
        int[] cnt = new int[batchSize];
        for (int g : groups) {
            cnt[g % batchSize]++;
        }
        int baseHappy = cnt[0]; // groups that perfectly fill a batch are always happy
        Map<Long, Integer> memo = new HashMap<>();
        int extraHappy = dfs(cnt, 0, batchSize, memo);
        return baseHappy + extraHappy;
    }

    private int dfs(int[] cnt, int curMod, int batchSize, Map<Long, Integer> memo) {
        // check if all counts are zero
        boolean empty = true;
        for (int i = 1; i < batchSize; i++) {
            if (cnt[i] != 0) {
                empty = false;
                break;
            }
        }
        if (empty) {
            return 0;
        }

        long key = encode(cnt, curMod);
        Integer cached = memo.get(key);
        if (cached != null) {
            return cached;
        }

        int best = 0;
        for (int r = 1; r < batchSize; r++) {
            if (cnt[r] == 0) continue;
            cnt[r]--;
            int nextMod = (curMod + r) % batchSize;
            int add = (curMod == 0) ? 1 : 0; // current group is happy if no leftover donuts
            int val = add + dfs(cnt, nextMod, batchSize, memo);
            if (val > best) best = val;
            cnt[r]++; // backtrack
        }

        memo.put(key, best);
        return best;
    }

    // Encode the state (counts of remainders 1..batchSize-1 and current modulo) into a long.
    // Each count is stored in 6 bits (allowing values up to 63, sufficient for the problem constraints).
    // The current modulo (0..batchSize-1) is stored in the lowest 4 bits.
    private long encode(int[] cnt, int curMod) {
        long key = curMod & 0xFL; // store curMod in lowest 4 bits
        for (int i = 1; i < cnt.length; i++) {
            key = (key << 6) | (cnt[i] & 0x3FL);
        }
        return key;
    }
}

