    public int stoneGameVIII(int[] stones) {
        int n = stones.length;
        if (n == 1) {
            return 0;
        }
        int[] prefix = new int[n];
        prefix[0] = stones[0];
        for (int i = 1; i < n; i++) {
            prefix[i] = prefix[i - 1] + stones[i];
        }
        int[] dp = new int[n + 1]; // dp[n] = 0 by default
        for (int i = n - 1; i >= 1; i--) {
