import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int maxBuilding(int n, int[][] restrictions) {
        // If there are no restrictions, the height can increase by 1 each step from building 1 (height 0)
        if (restrictions == null || restrictions.length == 0) {
            return n - 1;
        }

        // Add building 1 with height 0 and building n with a very large allowed height
        int m = restrictions.length + 2;
        int[][] all = new int[m][2];
        all[0][0] = 1;
        all[0][1] = 0;
        System.arraycopy(restrictions, 0, all, 1, restrictions.length);
        all[m - 1][0] = n;
        all[m - 1][1] = Integer.MAX_VALUE / 2; // avoid overflow in calculations

        // Sort by building id
        Arrays.sort(all, Comparator.comparingInt(a -> a[0]));

        // Forward pass: enforce the difference constraint
        for (int i = 1; i < m; i++) {
            int dist = all[i][0] - all[i - 1][0];
            all[i][1] = Math.min(all[i][1], all[i - 1][1] + dist);
        }

        // Backward pass: enforce the difference constraint from the right side
        for (int i = m - 2; i >= 0; i--) {
            int dist = all[i + 1][0] - all[i][0];
            all[i][1] = Math.min(all[i][1], all[i + 1][1] + dist);
        }

        int answer = 0;

        // Evaluate maximum possible height between each pair of consecutive restricted buildings
        for (int i = 0; i < m - 1; i++) {
            int id1 = all[i][0];
            int h1 = all[i][1];
            int id2 = all[i + 1][0];
            int h2 = all[i + 1][1];
            int dist = id2 - id1;

            // The highest point achievable between id1 and id2
            int localMax = Math.max(h1, h2) + (dist - Math.abs(h1 - h2)) / 2;
            answer = Math.max(answer, localMax);
        }

        // If the last restriction is before building n, we can keep increasing after it
        int[] last = all[m - 1];
        if (last[0] != n) {
            answer = Math.max(answer, last[1] + (n - last[0]));
        }

        return answer;
    }
}

