import java.util.Arrays;
import java.util.Comparator;
import java.util.PriorityQueue;

public class Solution {
    public int[] minInterval(int[][] intervals, int[] queries) {
        int n = intervals.length;
        int m = queries.length;
        // Sort intervals by left endpoint
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));

        // Indices of queries sorted by query value
        Integer[] qIdx = new Integer[m];
        for (int i = 0; i < m; i++) qIdx[i] = i;
        Arrays.sort(qIdx, Comparator.comparingInt(i -> queries[i]));

        // Min-heap ordered by interval size (right - left + 1)
        // Each element: [right, size]
        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));

        int[] ans = new int[m];
        int intPtr = 0;

        for (int idx : qIdx) {
            int q = queries[idx];

            // Add all intervals whose left <= q
            while (intPtr < n && intervals[intPtr][0] <= q) {
                int left = intervals[intPtr][0];
                int right = intervals[intPtr][1];
                int size = right - left + 1;
                heap.offer(new int[]{right, size});
                intPtr++;
            }

            // Remove intervals that end before q
            while (!heap.isEmpty() && heap.peek()[0] < q) {
                heap.poll();
            }

            ans[idx] = heap.isEmpty() ? -1 : heap.peek()[1];
        }

        return ans;
    }
}

