public class Solution {
    public int maximumPopulation(int[][] logs) {
        // Use a TreeMap to store the difference array (year -> delta)
        TreeMap<Integer, Integer> diff = new TreeMap<>();
        for (int[] log : logs) {
            int birth = log[0];
            int death = log[1];
            diff.put(birth, diff.getOrDefault(birth, 0) + 1);
            diff.put(death, diff.getOrDefault(death, 0) - 1);
        }

        int currentPopulation = 0;
        int maxPopulation = 0;
        int earliestYear = 0;

        for (Map.Entry<Integer, Integer> entry : diff.entrySet()) {
            currentPopulation += entry.getValue();
            if (currentPopulation > maxPopulation) {
                maxPopulation = currentPopulation;
                earliestYear = entry.getKey();
            }
        }

        return earliestYear;
    }
}

