public class Solution {
    public char[][] rotateTheBox(char[][] box) {
        int m = box.length;
        int n = box[0].length;

        // Apply gravity to the right for each row
        for (int i = 0; i < m; i++) {
            int empty = 0; // count of empty cells to the right
            for (int j = n - 1; j >= 0; j--) {
                char cell = box[i][j];
                if (cell == '.') {
                    empty++;
                } else if (cell == '#') {
                    if (empty > 0) {
                        box[i][j] = '.';
                        box[i][j + empty] = '#';
                    }
                } // obstacles '*' are ignored, they reset empty count
                else if (cell == '*') {
                    empty = 0;
                }
            }
        }

        // Rotate the box 90 degrees clockwise
        char[][] rotated = new char[n][m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                rotated[j][m - 1 - i] = box[i][j];
            }
        }

        return rotated;
    }
}

