public class Solution {
    public int maxValue(int n, int index, int maxSum) {
        long low = 1;
        long high = maxSum;
        long answer = 1;
        while (low <= high) {
            long mid = (low + high) >>> 1;
            if (canAchieve(mid, n, index, maxSum)) {
                answer = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return (int) answer;
    }

    private boolean canAchieve(long value, int n, int index, int maxSum) {
        long leftSum = calcSideSum(value, index + 1);
        long rightSum = calcSideSum(value, n - index);
        long total = leftSum + rightSum - value; // value counted twice
        return total <= maxSum;
    }

    // calculates minimal sum for a side of length len (including the peak value)
    // where the first element is 'value' and each next element decreases by at most 1,
    // but not below 1.
    private long calcSideSum(long value, int len) {
        if (len == 0) return 0;
        if (value >= len) {
            // decreasing sequence never reaches 1
            long first = value;
            long last = value - len + 1;
            return (first + last) * len / 2;
        } else {
            // sequence reaches 1 before covering all positions
            long decreasingCount = value; // from value down to 1
            long sumDecreasing = (value + 1) * value / 2;
            long remaining = len - decreasingCount;
            return sumDecreasing + remaining; // remaining positions are all 1
        }
    }
}

