import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int[] getOrder(int[][] tasks1) {
        int n = tasks1.length;
        // each element: [enqueueTime, processingTime, index]
        int[][] tasks = new int[n][3];
        for (int i = 0; i < n; i++) {
            tasks[i][0] = tasks1[i][0];
            tasks[i][1] = tasks1[i][1];
            tasks[i][2] = i;
        }
        // sort by enqueue time
        Arrays.sort(tasks, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            // tie‑breaker not required here, but keep deterministic order
            return Integer.compare(a[2], b[2]);
        });

        // priority queue ordered by processing time, then index
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> {
            if (a[1] != b[1]) return Integer.compare(a[1], b[1]);
            return Integer.compare(a[2], b[2]);
        });

        int[] order = new int[n];
        int orderPos = 0;
        long time = 0;
        int i = 0;

        while (i < n || !pq.isEmpty()) {
            if (pq.isEmpty() && time < tasks[i][0]) {
                time = tasks[i][0];
            }
            while (i < n && tasks[i][0] <= time) {
                pq.offer(tasks[i]);
                i++;
            }
            int[] cur = pq.poll();
            order[orderPos++] = cur[2];
            time += cur[1];
        }

        return order;
    }
}

