import java.util.*;

public class Solution {
    public int minSkips(int[] dist, int speed, int hoursBefore) {
        int n = dist.length;
        double[][] dp = new double[n][n + 1];
        double INF = 1e18;
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], INF);
        }

        double firstTime = (double) dist[0] / speed;
        for (int j = 0; j <= n; j++) {
            dp[0][j] = firstTime; // skips before first road are irrelevant
        }

        for (int i = 1; i < n; i++) {
            double travel = (double) dist[i] / speed;
            for (int j = 0; j <= i; j++) {
                // not skipping after previous road
                double prev = dp[i - 1][j];
                if (prev < INF) {
                    double time = Math.ceil(prev) + travel;
                    dp[i][j] = Math.min(dp[i][j], time);
                }
                // skipping after previous road
                if (j > 0) {
                    double prevSkip = dp[i - 1][j - 1];
                    if (prevSkip < INF) {
                        double timeSkip = prevSkip + travel;
                        dp[i][j] = Math.min(dp[i][j], timeSkip);
                    }
                }
            }
        }

        for (int j = 0; j <= n; j++) {
            if (dp[n - 1][j] <= hoursBefore + 1e-9) {
                return j;
            }
        }
        return -1;
    }
}

