public class Solution {
    public int[] getBiggestThree(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        // prefix sums for two diagonal directions
        int[][] diag1 = new int[m][n]; // down‑right
        int[][] diag2 = new int[m][n]; // down‑left

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                diag1[i][j] = grid[i][j];
                if (i > 0 && j > 0) {
                    diag1[i][j] += diag1[i - 1][j - 1];
                }

                diag2[i][j] = grid[i][j];
                if (i > 0 && j + 1 < n) {
                    diag2[i][j] += diag2[i - 1][j + 1];
                }
            }
        }

        // helper lambdas for diagonal sums
        // sum on down‑right diagonal from (x1,y1) to (x2,y2) inclusive
        java.util.function.BiFunction<int[], int[], Integer> drSum = (start, end) -> {
            int x1 = start[0], y1 = start[1];
            int x2 = end[0], y2 = end[1];
            int res = diag1[x2][y2];
            if (x1 > 0 && y1 > 0) {
                res -= diag1[x1 - 1][y1 - 1];
            }
            return res;
        };

        // sum on down‑left diagonal from (x1,y1) to (x2,y2) inclusive
        java.util.function.BiFunction<int[], int[], Integer> dlSum = (start, end) -> {
            int x1 = start[0], y1 = start[1];
            int x2 = end[0], y2 = end[1];
            int res = diag2[x2][y2];
            if (x1 > 0 && y1 + 1 < n) {
                res -= diag2[x1 - 1][y1 + 1];
            }
            return res;
        };

        Set<Integer> distinct = new HashSet<>();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                // size 0 rhombus (single cell)
                distinct.add(grid[i][j]);

                // maximal possible k for this top corner
                int maxK = Math.min(Math.min(m - 1 - i, j), n - 1 - j);
                for (int k = 1; k <= maxK; k++) {
                    // ensure bottom point stays inside grid
                    if (i + 2 * k >= m) break;

                    // corners
                    int topX = i, topY = j;
                    int leftX = i + k, leftY = j - k;
                    int bottomX = i + 2 * k, bottomY = j;
                    int rightX = i + k, rightY = j + k;

                    int sum1 = dlSum.apply(new int[]{topX, topY}, new int[]{leftX, leftY});      // top → left
                    int sum2 = drSum.apply(new int[]{leftX, leftY}, new int[]{bottomX, bottomY}); // left → bottom
                    int sum3 = dlSum.apply(new int[]{bottomX, bottomY}, new int[]{rightX, rightY}); // bottom → right
                    int sum4 = drSum.apply(new int[]{rightX, rightY}, new int[]{topX, topY});      // right → top

                    int total = sum1 + sum2 + sum3 + sum4
                            - grid[topX][topY] - grid[leftX][leftY] - grid[bottomX][bottomY] - grid[rightX][rightY];

                    distinct.add(total);
                }
            }
        }

        List<Integer> list = new ArrayList<>(distinct);
        list.sort(Collections.reverseOrder());

        int size = Math.min(3, list.size());
        int[] ans = new int[size];
        for (int i = 0; i < size; i++) {
            ans[i] = list.get(i);
        }
        return ans;
    }
}

