import java.util.Arrays;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int minWastedSpace(int[] packages, int[][] boxes) {
        int n = packages.length;
        Arrays.sort(packages);
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + packages[i];
        }

        long best = Long.MAX_VALUE;

        for (int[] supplier : boxes) {
            Arrays.sort(supplier);
            if (supplier[supplier.length - 1] < packages[n - 1]) {
                continue; // this supplier cannot fit the largest package
            }

            long waste = 0;
            int prevIdx = 0; // number of packages already assigned

            for (int boxSize : supplier) {
                int idx = upperBound(packages, boxSize);
                if (idx > prevIdx) {
                    long totalPkgSize = prefix[idx] - prefix[prevIdx];
                    waste += (long) boxSize * (idx - prevIdx) - totalPkgSize;
                }
                prevIdx = idx;
                if (prevIdx == n) {
                    break; // all packages are placed
                }
            }

            if (prevIdx == n) {
                best = Math.min(best, waste);
            }
        }

        if (best == Long.MAX_VALUE) {
            return -1;
        }
        return (int) (best % MOD);
    }

    // returns first index > target (i.e., upper bound)
    private int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

