import java.util.*;

public class Solution {
    private static final int MAX_BIT = 31; // enough for non‑negative ints

    private static class TrieNode {
        int[] child = new int[]{-1, -1};
        int cnt = 0;
    }

    private long countLessOrEqual(int[] nums, int K) {
        if (K < 0) return 0L;
        List<TrieNode> nodes = new ArrayList<>();
        nodes.add(new TrieNode()); // root at index 0
        long total = 0L;

        for (int num : nums) {
            total += query(nodes, num, K);
            insert(nodes, num);
        }
        return total;
    }

    private void insert(List<TrieNode> nodes, int num) {
        int nodeIdx = 0;
        for (int i = MAX_BIT; i >= 0; i--) {
            int bit = (num >>> i) & 1;
            int nextIdx = nodes.get(nodeIdx).child[bit];
            if (nextIdx == -1) {
                nextIdx = nodes.size();
                nodes.get(nodeIdx).child[bit] = nextIdx;
                nodes.add(new TrieNode());
            }
            nodeIdx = nextIdx;
            nodes.get(nodeIdx).cnt++;
        }
    }

    private long query(List<TrieNode> nodes, int num, int K) {
        int nodeIdx = 0;
        long res = 0L;
        for (int i = MAX_BIT; i >= 0 && nodeIdx != -1; i--) {
            int bitNum = (num >>> i) & 1;
            int bitK = (K >>> i) & 1;
            if (bitK == 1) {
                int sameBranch = nodes.get(nodeIdx).child[bitNum];
                if (sameBranch != -1) {
                    res += nodes.get(sameBranch).cnt;
                }
                nodeIdx = nodes.get(nodeIdx).child[1 - bitNum];
            } else {
                nodeIdx = nodes.get(nodeIdx).child[bitNum];
            }
        }
        return res;
    }

    public int countPairs(int[] nums, int low, int high) {
        long result = countLessOrEqual(nums, high) - countLessOrEqual(nums, low - 1);
        return (int) result;
    }
}

