import java.util.*;

public class Solution {
    public int longestBeautifulSubstring(String word) {
        int n = word.length();
        int maxLen = 0;
        int left = 0;
        int[] cnt = new int[5]; // a, e, i, o, u

        for (int right = 0; right < n; right++) {
            int curIdx = vowelIndex(word.charAt(right));

            // If the order breaks, start a new window from current character
            if (right > left) {
                int prevIdx = vowelIndex(word.charAt(right - 1));
                if (curIdx < prevIdx) {
                    // reset window
                    left = right;
                    Arrays.fill(cnt, 0);
                }
            }

            cnt[curIdx]++;

            // Check if current window contains all five vowels
            if (cnt[0] > 0 && cnt[1] > 0 && cnt[2] > 0 && cnt[3] > 0 && cnt[4] > 0) {
                maxLen = Math.max(maxLen, right - left + 1);
            }
        }

        return maxLen;
    }

    // Helper to map vowel character to index 0..4
    private int vowelIndex(char c) {
        switch (c) {
            case 'a': return 0;
            case 'e': return 1;
            case 'i': return 2;
            case 'o': return 3;
            case 'u': return 4;
            default:  return -1; // should never happen for valid input
        }
    }
}

