import java.util.*;

public class Solution {
    public boolean findRotation(int[][] mat, int[][] target) {
        int n = mat.length;
        for (int k = 0; k < 4; k++) {
            if (areEqual(mat, target)) {
                return true;
            }
            rotate90Clockwise(mat);
        }
        return false;
    }

    private boolean areEqual(int[][] a, int[][] b) {
        int n = a.length;
        for (int i = 0; i < n; i++) {
            if (!Arrays.equals(a[i], b[i])) {
                return false;
            }
        }
        return true;
    }

    // Rotate the matrix 90 degrees clockwise in-place:
    // 1) Reverse the rows (top to bottom)
    // 2) Transpose the matrix
    private void rotate90Clockwise(int[][] matrix) {
        int n = matrix.length;
        // Reverse rows
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            int[] temp = matrix[i];
            matrix[i] = matrix[j];
            matrix[j] = temp;
        }
        // Transpose
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int tmp = matrix[i][j];
                matrix[i][j] = matrix[j][i];
                matrix[j][i] = tmp;
            }
        }
    }
}

