import java.util.Arrays;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int minAbsoluteSumDiff(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long totalSum = 0;
        for (int i = 0; i < n; i++) {
            totalSum += Math.abs((long) nums1[i] - nums2[i]);
        }

        int[] sorted = nums1.clone();
        Arrays.sort(sorted);

        long maxGain = 0;
        for (int i = 0; i < n; i++) {
            long currentDiff = Math.abs((long) nums1[i] - nums2[i]);
            int target = nums2[i];

            int idx = Arrays.binarySearch(sorted, target);
            if (idx < 0) {
                idx = -idx - 1;
            }

            long bestDiff = currentDiff;

            if (idx < n) {
                long candDiff = Math.abs((long) sorted[idx] - target);
                if (candDiff < bestDiff) {
                    bestDiff = candDiff;
                }
            }
            if (idx > 0) {
                long candDiff = Math.abs((long) sorted[idx - 1] - target);
                if (candDiff < bestDiff) {
                    bestDiff = candDiff;
                }
            }

            long gain = currentDiff - bestDiff;
            if (gain > maxGain) {
                maxGain = gain;
            }
        }

        long result = (totalSum - maxGain) % MOD;
        if (result < 0) {
            result += MOD;
        }
        return (int) result;
    }
}

