import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int sumOfFlooredPairs(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }

        int max = 0;
        for (int v : nums) {
            if (v > max) max = v;
        }

        int[] freq = new int[max + 1];
        for (int v : nums) {
            freq[v]++;
        }

        long[] prefix = new long[max + 1];
        prefix[0] = freq[0];
        for (int i = 1; i <= max; i++) {
            prefix[i] = prefix[i - 1] + freq[i];
        }

        long ans = 0L;

        for (int divisor = 1; divisor <= max; divisor++) {
            int divCount = freq[divisor];
            if (divCount == 0) continue;

            for (int multiple = divisor; multiple <= max; multiple += divisor) {
                int high = Math.min(multiple + divisor - 1, max);
                long cntInRange = prefix[high] - (multiple > 0 ? prefix[multiple - 1] : 0);
                if (cntInRange == 0) continue;

                long quotient = multiple / divisor; // floor value for this range
                long add = (quotient % MOD) * (cntInRange % MOD) % MOD;
                add = add * divCount % MOD;
                ans = (ans + add) % MOD;
            }
        }

        return (int) ans;
    }
}

