public class Solution {
    public boolean canReach(String s, int minJump, int maxJump) {
        int n = s.length();
        if (n == 0) return false;
        boolean[] reachable = new boolean[n];
        reachable[0] = true;
        int windowSum = 0; // number of reachable positions in the current sliding window

        for (int i = 1; i < n; i++) {
            // Add the position that becomes reachable for the window when i - minJump >= 0
            int addIdx = i - minJump;
            if (addIdx >= 0 && reachable[addIdx]) {
                windowSum++;
            }

            // Remove the position that falls out of the window when i - maxJump - 1 >= 0
            int removeIdx = i - maxJump - 1;
            if (removeIdx >= 0 && reachable[removeIdx]) {
                windowSum--;
            }

            // Current position i is reachable if it is '0' and there is at least one reachable
            // position in the window [i - maxJump, i - minJump]
            if (s.charAt(i) == '0' && windowSum > 0) {
                reachable[i] = true;
            }
        }

        return reachable[n - 1];
    }
}

