import java.util.PriorityQueue;

public class Solution {
    public int[] assignTasks(int[] servers, int[] tasks) {
        int n = servers.length;
        int m = tasks.length;
        // Free servers: ordered by weight, then index
        PriorityQueue<int[]> free = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return a[0] - b[0];
            return a[1] - b[1];
        });
        // Busy servers: ordered by time when they become free, then weight, then index
        PriorityQueue<int[]> busy = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return a[0] - b[0];
            if (a[1] != b[1]) return a[1] - b[1];
            return a[2] - b[2];
        });

        for (int i = 0; i < n; i++) {
            free.offer(new int[]{servers[i], i}); // {weight, index}
        }

        int[] ans = new int[m];
        int time = 0;

        for (int j = 0; j < m; j++) {
            // current time cannot be earlier than the arrival time of task j
            time = Math.max(time, j);

            // release servers that have become free by current time
            while (!busy.isEmpty() && busy.peek()[0] <= time) {
                int[] s = busy.poll();
                free.offer(new int[]{s[1], s[2]}); // {weight, index}
            }

            // if no free server, jump to the next moment a server becomes free
            if (free.isEmpty()) {
                time = busy.peek()[0];
                while (!busy.isEmpty() && busy.peek()[0] <= time) {
                    int[] s = busy.poll();
                    free.offer(new int[]{s[1], s[2]});
                }
            }

            // assign task j to the best free server
            int[] server = free.poll();
            ans[j] = server[1];
            busy.offer(new int[]{time + tasks[j], server[0], server[1]}); // {freeTime, weight, index}
        }

        return ans;
    }
}

