import java.util.*;

public class Solution {
    public int largestMagicSquare(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        // Row prefix sums
        int[][] rowPref = new int[m][n + 1];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                rowPref[i][j + 1] = rowPref[i][j] + grid[i][j];
            }
        }

        // Column prefix sums
        int[][] colPref = new int[m + 1][n];
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < m; i++) {
                colPref[i + 1][j] = colPref[i][j] + grid[i][j];
            }
        }

        // Main diagonal prefix (top‑left to bottom‑right)
        int[][] diag1 = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int prev = (i > 0 && j > 0) ? diag1[i - 1][j - 1] : 0;
                diag1[i][j] = prev + grid[i][j];
            }
        }

        // Anti‑diagonal prefix (top‑right to bottom‑left)
        int[][] diag2 = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = n - 1; j >= 0; j--) {
                int prev = (i > 0 && j + 1 < n) ? diag2[i - 1][j + 1] : 0;
                diag2[i][j] = prev + grid[i][j];
            }
        }

        int maxSide = Math.min(m, n);
        for (int k = maxSide; k >= 1; k--) {
            for (int r = 0; r + k <= m; r++) {
                for (int c = 0; c + k <= n; c++) {
                    // target sum from first row
                    int target = rowPref[r][c + k] - rowPref[r][c];
                    boolean ok = true;

                    // check rows
                    for (int i = 0; i < k && ok; i++) {
                        int sum = rowPref[r + i][c + k] - rowPref[r + i][c];
                        if (sum != target) ok = false;
                    }

                    // check columns
                    for (int j = 0; j < k && ok; j++) {
                        int sum = colPref[r + k][c + j] - colPref[r][c + j];
                        if (sum != target) ok = false;
                    }

                    // check main diagonal
                    if (ok) {
                        int d1 = diag1[r + k - 1][c + k - 1];
                        int sub = (r > 0 && c > 0) ? diag1[r - 1][c - 1] : 0;
                        if (d1 - sub != target) ok = false;
                    }

                    // check anti‑diagonal
                    if (ok) {
                        int d2 = diag2[r + k - 1][c];
                        int sub = (r > 0 && c + k < n) ? diag2[r - 1][c + k] : 0;
                        if (d2 - sub != target) ok = false;
                    }

                    if (ok) return k;
                }
            }
        }
        return 1; // at least 1x1 exists
    }
}

