public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int maxNiceDivisors(int primeFactors) {
        if (primeFactors <= 3) {
            return primeFactors % (int) MOD;
        }

        long cnt3 = primeFactors / 3;
        int remainder = primeFactors % 3;
        long cnt2 = 0;

        if (remainder == 1) {
            cnt3 -= 1;
            cnt2 = 2;
        } else if (remainder == 2) {
            cnt2 = 1;
        }

        long result = (powMod(3, cnt3) * powMod(2, cnt2)) % MOD;
        return (int) result;
    }

    private long powMod(long base, long exp) {
        long result = 1L;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            e >>= 1;
        }
        return result;
    }
}

