        int max = 0;
        int len1 = n1.length;
        int len2 = n2.length;
        while (i < len1 && j < len2) {
            if (n1[i] <= n2[j]) {
                // valid pair, update max distance
                max = Math.max(max, j - i);
                j++; // try to increase distance
            } else {
                // n1[i] > n2[j], need to move i forward
                i++;
                // ensure j is not left behind i
                if (j < i) {
                    j = i;
                }
            }
        }
        return max;
    }
}

