public class Solution {
    public int maximumRemovals(String s, String p, int[] removable) {
        int left = 0;
        int right = removable.length;
        while (left < right) {
            int mid = (left + right + 1) >>> 1; // upper mid
            if (isSubsequenceAfterRemoval(s, p, removable, mid)) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }
        return left;
    }

    private boolean isSubsequenceAfterRemoval(String s, String p, int[] removable, int k) {
        int n = s.length();
        boolean[] removed = new boolean[n];
        for (int i = 0; i < k; i++) {
            removed[removable[i]] = true;
        }
        int pi = 0;
        for (int i = 0; i < n && pi < p.length(); i++) {
            if (removed[i]) {
                continue;
            }
            if (s.charAt(i) == p.charAt(pi)) {
                pi++;
            }
        }
        return pi == p.length();
    }
}

