public class Solution {
    public int minSideJumps(int[] obstacles) {
        int n = obstacles.length - 1;
        final int INF = 1_000_000;
        // dp for lanes 1,2,3 (index 0,1,2)
        int[] dp = new int[3];
        dp[0] = 1; // lane 1 needs one side jump from start lane 2
        dp[1] = 0; // start lane
        dp[2] = 1; // lane 3 needs one side jump from start lane 2

        for (int i = 1; i < n; i++) {
            // block lanes with obstacles at position i
            for (int lane = 0; lane < 3; lane++) {
                if (obstacles[i] == lane + 1) {
                    dp[lane] = INF;
                }
            }
            // try to improve each unblocked lane by side jumping from the best other lane
            for (int lane = 0; lane < 3; lane++) {
                if (obstacles[i] == lane + 1) continue; // still blocked
                int minOther = INF;
                for (int other = 0; other < 3; other++) {
                    if (other != lane) {
                        minOther = Math.min(minOther, dp[other]);
                    }
                }
                dp[lane] = Math.min(dp[lane], 1 + minOther);
            }
        }
        // answer is minimal jumps among the three lanes at point n
        return Math.min(dp[0], Math.min(dp[1], dp[2]));
    }
}

