public class Solution {
    public int largestPathValue(String colors, int[][] edges) {
        int n = colors.length();
        List<Integer>[] graph = new ArrayList[n];
        int[] indegree = new int[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int from = e[0];
            int to = e[1];
            graph[from].add(to);
            indegree[to]++;
        }

        // DP table: dp[node][color] = max count of that color on any path ending at node
        int[][] dp = new int[n][26];
        Queue<Integer> queue = new ArrayDeque<>();

        // Initialize queue with nodes of indegree 0 and set base dp values
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                queue.offer(i);
            }
            int colorIdx = colors.charAt(i) - 'a';
            dp[i][colorIdx] = 1;
        }

        int visited = 0;
        int answer = 0;

        while (!queue.isEmpty()) {
            int u = queue.poll();
            visited++;

            // Update global answer with the best color count at node u
            for (int c = 0; c < 26; c++) {
                answer = Math.max(answer, dp[u][c]);
            }

            for (int v : graph[u]) {
                // Propagate dp values to neighbor v
                for (int c = 0; c < 26; c++) {
                    int add = (colors.charAt(v) - 'a' == c) ? 1 : 0;
                    dp[v][c] = Math.max(dp[v][c], dp[u][c] + add);
                }
                indegree[v]--;
                if (indegree[v] == 0) {
                    queue.offer(v);
                }
            }
        }

        // If not all nodes were visited, there is a cycle
        if (visited != n) {
            return -1;
        }
        return answer;
    }
}

