import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int shortestPathAllKeys(String[] stringGrid) {
        if (stringGrid == null || stringGrid.length == 0) {
            return -1;
        }
        int m = stringGrid.length;
        int n = stringGrid[0].length();
        char[][] grid = new char[m][n];
        int startX = -1, startY = -1;
        int totalKeys = 0;

        for (int i = 0; i < m; i++) {
            grid[i] = stringGrid[i].toCharArray();
            for (int j = 0; j < n; j++) {
                char c = grid[i][j];
                if (c == '@') {
                    startX = i;
                    startY = j;
                } else if (c >= 'a' && c <= 'f') {
                    // keys are limited to first 6 letters
                    totalKeys = Math.max(totalKeys, c - 'a' + 1);
                }
            }
        }

        int allKeysMask = (1 << totalKeys) - 1;
        // visited[x][y][mask]
        boolean[][][] visited = new boolean[m][n][1 << totalKeys];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startX, startY, 0});
        visited[startX][startY][0] = true;

        int steps = 0;
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int s = 0; s < size; s++) {
                int[] cur = queue.poll();
                int x = cur[0];
                int y = cur[1];
                int mask = cur[2];

                if (mask == allKeysMask) {
                    return steps;
                }

                for (int dir = 0; dir < 4; dir++) {
                    int nx = x + dx[dir];
                    int ny = y + dy[dir];
                    int nmask = mask;

                    if (nx < 0 || nx >= m || ny < 0 || ny >= n) {
                        continue;
                    }
                    char cell = grid[nx][ny];
                    if (cell == '#') {
                        continue; // wall
                    }

                    // If it's a key, pick it up
                    if (cell >= 'a' && cell <= 'f') {
                        int keyBit = 1 << (cell - 'a');
                        nmask = mask | keyBit;
                    }

                    // If it's a lock, ensure we have the key
                    if (cell >= 'A' && cell <= 'F') {
                        int keyBit = 1 << (cell - 'A');
                        if ((mask & keyBit) == 0) {
                            continue; // don't have the key yet
                        }
                    }

                    if (!visited[nx][ny][nmask]) {
                        visited[nx][ny][nmask] = true;
                        queue.offer(new int[]{nx, ny, nmask});
                    }
                }
            }
            steps++;
        }

        return -1; // impossible to collect all keys
    }
}

