public class Solution {
    public List<Integer> splitIntoFibonacci(String num) {
        List<Integer> result = new ArrayList<>();
        backtrack(num, 0, result);
        return result;
    }

    private boolean backtrack(String s, int index, List<Integer> path) {
        if (index == s.length()) {
            return path.size() >= 3;
        }

        long cur = 0;
        for (int i = index; i < s.length(); i++) {
            // avoid numbers with leading zeros
            if (i > index && s.charAt(index) == '0') {
                break;
            }

            cur = cur * 10 + (s.charAt(i) - '0');
            if (cur > Integer.MAX_VALUE) {
                break;
            }

            int curInt = (int) cur;

            int size = path.size();
            if (size >= 2) {
                long sum = (long) path.get(size - 2) + (long) path.get(size - 1);
                if (cur < sum) {
                    continue; // need larger number
                } else if (cur > sum) {
                    break; // further numbers will only be larger
                }
            }

            path.add(curInt);
            if (backtrack(s, i + 1, path)) {
                return true;
            }
            path.remove(path.size() - 1);
        }
        return false;
    }
}

