import java.util.Set;

public class Solution {
    public boolean splitArraySameAverage(int[] nums) {
        int n = nums.length;
        if (n == 1) return false;
        int total = 0;
        for (int v : nums) total += v;

        // dp[k] holds all possible sums using exactly k elements
        @SuppressWarnings("unchecked")
        Set<Integer>[] dp = new HashSet[n + 1];
        for (int i = 0; i <= n; i++) dp[i] = new HashSet<>();
        dp[0].add(0);

        for (int num : nums) {
            // iterate sizes backwards to avoid reuse within same iteration
            for (int size = n; size >= 1; size--) {
                if (dp[size - 1].isEmpty()) continue;
                for (int prevSum : dp[size - 1]) {
                    dp[size].add(prevSum + num);
                }
            }
        }

        // check for any valid subset size k (1 <= k < n)
        for (int k = 1; k < n; k++) {
            if ((total * k) % n != 0) continue; // required sum must be integer
            int target = (total * k) / n;
            if (dp[k].contains(target)) {
                return true;
            }
        }
        return false;
    }
}

