            graph[poorerPerson].add(richerPerson);
        }

        int[] answer = new int[n];
        // initialize answer with self
        for (int i = 0; i < n; i++) {
            answer[i] = i;
        }
        boolean[] visited = new boolean[n];
        for (int i = 0; i < n; i++) {
            dfs(i, graph, quiet, answer, visited);
        }
        return answer;
