        if (visited[node]) {
            return answer[node];
        }
        visited[node] = true;
        int best = node;
        for (int richerNeighbor : graph[node]) {
            int candidate = dfs(richerNeighbor, graph, quiet, answer, visited);
            if (quiet[candidate] < quiet[best]) {
                best = candidate;
            }
        }
        answer[node] = best;
        return best;
    }
}

