public class Solution {
    public double largestSumOfAverages(int[] nums, int k) {
        int n = nums.length;
        if (k > n) {
            k = n;
        }
        double[] prefix = new double[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        double[][] dp = new double[n + 1][k + 1];
        // base case: one group
        for (int i = 1; i <= n; i++) {
            dp[i][1] = prefix[i] / i;
        }

        for (int groups = 2; groups <= k; groups++) {
            for (int i = groups; i <= n; i++) {
                double best = 0.0;
                // try splitting after position t (t elements in previous groups)
                for (int t = groups - 1; t < i; t++) {
                    double cur = dp[t][groups - 1] + (prefix[i] - prefix[t]) / (i - t);
                    if (cur > best) {
                        best = cur;
                    }
                }
                dp[i][groups] = best;
            }
        }

        return dp[n][k];
    }
}

