import java.util.Queue;
import java.util.Set;

public class Solution {
    public int racecar(int target) {
        if (target == 0) {
            return 0;
        }

        class State {
            int position;
            int speed;

            State(int p, int s) {
                this.position = p;
                this.speed = s;
            }
        }

        Queue<State> queue = new LinkedList<>();
        Set<Long> visited = new HashSet<>();

        queue.offer(new State(0, 1));
        visited.add(encode(0, 1));

        int steps = 0;
        // reasonable bounds to avoid infinite search
        int maxPos = target * 2;
        int minPos = -target;

        while (!queue.isEmpty()) {
            int size = queue.size();
            steps++;
            for (int i = 0; i < size; i++) {
                State cur = queue.poll();

                // Accelerate
                int nextPosA = cur.position + cur.speed;
                int nextSpeedA = cur.speed * 2;
                if (nextPosA == target) {
                    return steps;
                }
                if (nextPosA <= maxPos && nextPosA >= minPos) {
                    long codeA = encode(nextPosA, nextSpeedA);
                    if (!visited.contains(codeA)) {
                        visited.add(codeA);
                        queue.offer(new State(nextPosA, nextSpeedA));
                    }
                }

                // Reverse
                int nextSpeedR = cur.speed > 0 ? -1 : 1;
                int nextPosR = cur.position; // position unchanged
                if (nextPosR == target) {
                    return steps;
                }
                long codeR = encode(nextPosR, nextSpeedR);
                if (!visited.contains(codeR)) {
                    visited.add(codeR);
                    queue.offer(new State(nextPosR, nextSpeedR));
                }
            }
        }
        // Should never reach here for valid inputs
        return -1;
    }

    private long encode(int position, int speed) {
        return ((long) position << 32) ^ (speed & 0xffffffffL);
    }
}

