public class Solution {
    public String decodeAtIndex(String s, int k) {
        long length = 0;
        // First pass: compute the length of the decoded string
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                int d = c - '0';
                length *= d;
            } else {
                length += 1;
            }
        }

        long target = k;
        // Second pass: iterate backwards to find the k-th character
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                int d = c - '0';
                length /= d;
                target = target % length;
                if (target == 0) {
                    target = length;
                }
            } else {
                if (target == length || target == 0) {
                    return String.valueOf(c);
                }
                length -= 1;
            }
        }
        return "";
    }
}

