import java.util.HashMap;
import com_github_leetcode.TreeNode;

public class Solution {
    private HashMap<Integer, Integer> postIndexMap;

    public TreeNode constructFromPrePost(int[] preorder, int[] postorder) {
        int n = preorder.length;
        postIndexMap = new HashMap<>(n * 2);
        for (int i = 0; i < n; i++) {
            postIndexMap.put(postorder[i], i);
        }
        return build(preorder, 0, n - 1, postorder, 0, n - 1);
    }

    private TreeNode build(int[] pre, int preL, int preR,
                           int[] post, int postL, int postR) {
        if (preL > preR) {
            return null;
        }
        TreeNode root = new TreeNode(pre[preL]);
        if (preL == preR) {
            return root;
        }

        // The next element in preorder is the left child root
        int leftRootVal = pre[preL + 1];
        int leftRootIdxInPost = postIndexMap.get(leftRootVal);
        int leftSize = leftRootIdxInPost - postL + 1;

        root.left = build(pre, preL + 1, preL + leftSize,
                          post, postL, leftRootIdxInPost);
        root.right = build(pre, preL + leftSize + 1, preR,
                           post, leftRootIdxInPost + 1, postR - 1);
        return root;
    }
}

