public class Solution {

    // Interface provided by the judge
    public interface Master {
        /**
         * @param word The guessed word, must be from the original wordlist.
         * @return The number of exact matches (value and position) with the secret word,
         *         or -1 if the guessed word is not in the wordlist.
         */
        int guess(String word);
    }

    public void findSecretWord(String[] wordlist, Master master) {
        List<String> candidates = new ArrayList<>();
        Collections.addAll(candidates, wordlist);
        int attempts = 0;

        while (attempts < 10 && !candidates.isEmpty()) {
            // Choose the next guess using minimax strategy
            String guessWord = selectBestGuess(candidates);
            int matchCount = master.guess(guessWord);
            attempts++;

            if (matchCount == 6) {
                // Guessed correctly
                return;
            }

            // Filter candidates that would give the same match count with guessWord
            List<String> nextCandidates = new ArrayList<>();
            for (String w : candidates) {
                if (match(guessWord, w) == matchCount) {
                    nextCandidates.add(w);
                }
            }
            candidates = nextCandidates;
        }
    }

    // Select the word that minimizes the maximum group size for any possible match count
    private String selectBestGuess(List<String> candidates) {
        int minMaxGroup = Integer.MAX_VALUE;
        String bestWord = candidates.get(0);

        for (String candidate : candidates) {
            int[] count = new int[7]; // match counts from 0 to 6
            for (String other : candidates) {
                if (candidate.equals(other)) continue;
                int m = match(candidate, other);
                count[m]++;
            }
            int maxGroup = 0;
            for (int c : count) {
                if (c > maxGroup) maxGroup = c;
            }
            if (maxGroup < minMaxGroup) {
                minMaxGroup = maxGroup;
                bestWord = candidate;
            }
        }
        return bestWord;
    }

    // Compute number of positions with the same character
    private int match(String a, String b) {
        int matches = 0;
        for (int i = 0; i < 6; i++) {
            if (a.charAt(i) == b.charAt(i)) {
                matches++;
            }
        }
        return matches;
    }
}

