import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public int numBusesToDestination(int[][] routes, int source, int target) {
        if (source == target) {
            return 0;
        }

        // Map each stop to the list of routes (bus indices) that pass through it
        Map<Integer, List<Integer>> stopToRoutes = new HashMap<>();
        for (int i = 0; i < routes.length; i++) {
            for (int stop : routes[i]) {
                stopToRoutes.computeIfAbsent(stop, k -> new ArrayList<>()).add(i);
            }
        }

        // If either source or target is not present in any route, impossible
        if (!stopToRoutes.containsKey(source) || !stopToRoutes.containsKey(target)) {
            return -1;
        }

        // BFS over routes
        Queue<Integer> queue = new ArrayDeque<>();
        boolean[] visitedRoute = new boolean[routes.length];
        int busesTaken = 1; // first level corresponds to taking one bus

        // Initialize queue with all routes that contain the source stop
        for (int routeIdx : stopToRoutes.get(source)) {
            queue.offer(routeIdx);
            visitedRoute[routeIdx] = true;
        }

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int curRoute = queue.poll();

                // If current route reaches the target stop, return the number of buses taken
                for (int stop : routes[curRoute]) {
                    if (stop == target) {
                        return busesTaken;
                    }
                }

                // Explore neighboring routes via shared stops
                for (int stop : routes[curRoute]) {
                    List<Integer> neighborRoutes = stopToRoutes.get(stop);
                    if (neighborRoutes == null) continue;
                    for (int nextRoute : neighborRoutes) {
                        if (!visitedRoute[nextRoute]) {
                            visitedRoute[nextRoute] = true;
                            queue.offer(nextRoute);
                        }
                    }
                    // Optional: clear to prevent re‑processing the same stop later
                    neighborRoutes.clear();
                }
            }
            busesTaken++;
        }

        return -1; // target not reachable
    }
}

package referenz;


public class Solution {
    public int mirrorReflection(int p, int q) {
        int g = gcd(p, q);
        // Number of extensions in x and y directions
        int m = q / g; // l / p
        int n = p / g; // l / q

        boolean mOdd = (m & 1) == 1;
        boolean nOdd = (n & 1) == 1;

        if (mOdd && !nOdd) {
            return 0; // (p,0)
        } else if (mOdd && nOdd) {
            return 1; // (p,p)
        } else if (!mOdd && nOdd) {
            return 2; // (0,p)
        }
        // This case should not occur with valid inputs
        return -1;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

