import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public double mincostToHireWorkers(int[] quality, int[] wage, int k) {
        int n = quality.length;
        Worker[] workers = new Worker[n];
        for (int i = 0; i < n; i++) {
            workers[i] = new Worker(quality[i], wage[i]);
        }
        // sort by wage/quality ratio ascending
        Arrays.sort(workers, (a, b) -> Double.compare(a.ratio, b.ratio));

        // max-heap to keep the k smallest qualities (by removing largest when size > k)
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);
        long sumQuality = 0;
        double answer = Double.MAX_VALUE;

        for (Worker w : workers) {
            maxHeap.offer(w.quality);
            sumQuality += w.quality;

            if (maxHeap.size() > k) {
                sumQuality -= maxHeap.poll(); // remove largest quality
            }

            if (maxHeap.size() == k) {
                double cost = sumQuality * w.ratio;
                if (cost < answer) {
                    answer = cost;
                }
            }
        }

        return answer;
    }

    private static class Worker {
        int quality;
        double ratio;

        Worker(int quality, int wage) {
            this.quality = quality;
            this.ratio = (double) wage / quality;
        }
    }
}

