import java.util.Arrays;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int sumSubseqWidths(int[] nums) {
        int n = nums.length;
        Arrays.sort(nums);
        long[] pow2 = new long[n];
        pow2[0] = 1;
        for (int i = 1; i < n; i++) {
            pow2[i] = (pow2[i - 1] << 1) % MOD;
        }

        long result = 0;
        for (int i = 0; i < n; i++) {
            long maxContribution = pow2[i];
            long minContribution = pow2[n - 1 - i];
            long diff = (maxContribution - minContribution + MOD) % MOD;
            result = (result + (nums[i] % MOD) * diff) % MOD;
        }
        return (int) result;
    }
}

