import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numFactoredBinaryTrees(int[] arr) {
        int n = arr.length;
        Arrays.sort(arr);
        Map<Integer, Integer> indexMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            indexMap.put(arr[i], i);
        }

        long[] dp = new long[n];
        Arrays.fill(dp, 1L); // each number alone forms a tree

        for (int i = 0; i < n; i++) {
            long cur = 1L; // start with the single-node tree
            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int right = arr[i] / arr[j];
                    Integer k = indexMap.get(right);
                    if (k != null) {
                        cur = (cur + dp[j] * dp[k]) % MOD;
                    }
                }
            }
            dp[i] = cur;
        }

        long result = 0L;
        for (long val : dp) {
            result = (result + val) % MOD;
        }
        return (int) result;
    }
}

