import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public boolean canVisitAllRooms(List<List<Integer>> rooms) {
        if (rooms == null) {
            return false;
        }
        int n = rooms.size();
        if (n == 0) {
            return true;
        }

        Set<Integer> visited = new HashSet<>();
        Deque<Integer> stack = new ArrayDeque<>();

        visited.add(0);
        stack.push(0);

        while (!stack.isEmpty()) {
            int current = stack.pop();
            for (int key : rooms.get(current)) {
                if (!visited.contains(key)) {
                    visited.add(key);
                    stack.push(key);
                }
            }
        }

        return visited.size() == n;
    }
}

package referenz;


public class Solution {
    public int numFriendRequests(int[] ages) {
        int[] count = new int[121];
        for (int age : ages) {
            if (age >= 0 && age <= 120) {
                count[age]++;
            }
        }

        int[] prefix = new int[121];
        prefix[0] = count[0];
        for (int i = 1; i <= 120; i++) {
            prefix[i] = prefix[i - 1] + count[i];
        }

        long totalRequests = 0L;
        for (int age = 15; age <= 120; age++) {
            int cnt = count[age];
            if (cnt == 0) continue;

            int low = age / 2 + 7;
            // number of people with age in (low, age] inclusive
            int eligible = prefix[age] - prefix[low];
            // each person of this age can send to (eligible - 1) others (exclude self)
            totalRequests += (long) cnt * (eligible - 1);
        }

        return (int) totalRequests;
    }
}

