import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;

public class Solution {
    public int reachableNodes(int[][] edges, int maxMoves, int n) {
        // Build adjacency list for the original graph.
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            int cnt = e[2];
            int w = cnt + 1; // weight of the edge in the original graph
            graph[u].add(new int[]{v, w});
            graph[v].add(new int[]{u, w});
        }

        // Dijkstra's algorithm to find shortest distances from node 0.
        long[] dist = new long[n];
        for (int i = 0; i < n; i++) {
            dist[i] = Long.MAX_VALUE;
        }
        dist[0] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.offer(new long[]{0, 0}); // {distance, node}
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int) cur[1];
            if (d != dist[u]) continue;
            for (int[] nb : graph[u]) {
                int v = nb[0];
                int w = nb[1];
                long nd = d + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.offer(new long[]{nd, v});
                }
            }
        }

        // Count reachable original nodes.
        long reachable = 0;
        for (int i = 0; i < n; i++) {
            if (dist[i] <= maxMoves) {
                reachable++;
            }
        }

        // Count reachable subdivided nodes on each edge.
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            int cnt = e[2];
            long fromU = Math.max(0, maxMoves - dist[u]);
            long fromV = Math.max(0, maxMoves - dist[v]);
            long used = Math.min(cnt, fromU + fromV);
            reachable += used;
        }

        return (int) reachable;
    }
}
